<script setup>
import {ref} from 'vue'
import {useRouter} from 'vue-router'
import {api,session} from '../lib/api.js'
const router=useRouter(),email=ref(''),password=ref(''),totp=ref(''),showTotp=ref(false),error=ref(''),working=ref(false)
async function submit(){error.value='';working.value=true;try{session.setTokens(await api('/auth/login',{method:'POST',body:{email:email.value,password:password.value,totp:totp.value||undefined}}));router.push('/')}catch(e){error.value=e.message;if(e.message.includes('TOTP'))showTotp.value=true}finally{working.value=false}}
</script>
<template><div class="login-screen"><div class="login-art"><span class="eyebrow">WINFIRE / SECURE</span><div class="login-symbol"><img src="/winfire-mark.png" alt=""></div><h1>Control every edge.<br><em>See every change.</em></h1><p>Windows Firewall policy, verification and identity protection in one control plane.</p><div class="login-grid"></div></div><form class="login-form glass" @submit.prevent="submit"><span class="eyebrow">OPERATOR ACCESS</span><h2>Welcome back</h2><p>Sign in to the control plane.</p><label>Email address<input v-model="email" type="email" autocomplete="username" required placeholder="you@company.com"></label><label>Password<input v-model="password" type="password" autocomplete="current-password" required placeholder="••••••••••••"></label><label v-if="showTotp">Authenticator code<input v-model="totp" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="one-time-code" required placeholder="000000"></label><div v-if="error" class="error-msg">{{error}}</div><button class="primary" type="submit" :disabled="working">{{working?'Signing in…':'Sign in'}} <i class="mdi mdi-arrow-right"></i></button><small>Authorized access only. All actions are audited.</small></form></div></template>
